-- 3. Queries. Change @SYNC_DT to look at another run.
DECLARE @SYNC_DT DATETIME2(0) = '2026-12-10 11:00:00';

-- Parent flow: > 0 = scenario 1 (XD06 then XD07), 0 = scenario 2 (XD07 only)
SELECT COUNT(*) AS GTOPAS_ROWS FROM ['-- =====================================================================================================', '-- Crossdock staging: get queries of the robot XD07 per OPERATION_TYPE (SQL Server)', '-- Generated by deliverables/function_list_v2/erd/proposal_staging_sync/simulation/sql_studio/build_sql_studio.py', '-- Read-only DB user. @SYNC_DT = SYNC_DT of the run, given by the parent flow. The robot itself reads the three files with', '-- FILE_NO (see crossdock_staging_sync.sql, section 5); these queries split the same rows per OPERATION_TYPE to check a run.', '-- Columns in the order of the templates (LLM9Q910 / LLM9Q880), helper columns last. EFFECTIVE_MONTH_YEAR (MM/YYYY):', '-- the robot splits it into Effective Month and Effective Year. Example runs: data of crossdock_staging_simulation.sql.', '--   OPERATION_TYPE  example run           upload order', '--   1               2026-12-03 11:00:00   1 EXPORT_PRE -> 2 KANBAN', '--   2               2026-12-03 11:00:00   2 KANBAN -> 3 EXPORT_POST', '--   3               2026-12-28 10:00:00   2 KANBAN -> 3 EXPORT_POST', '--   4               2026-12-05 11:00:00   2 KANBAN -> 3 EXPORT_POST', '--   5               2026-12-08 11:00:00   3 EXPORT_POST only', '-- =====================================================================================================', '', '-- ----- OPERATION_TYPE 1 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-03 11:00:00';", "-- OPERATION_TYPE 1: Max down. File 1 EXPORT_PRE first (the destinations go down while AP POLE still has the old Max), then file 2 KANBAN with the new Max. No EXPORT_POST row for the part.\n-- Upload order of these parts: 1 EXPORT_PRE -> 2 KANBAN\n-- Kanban rows -> file 2 KANBAN (LLM9Q910)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 1\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 1 EXPORT_PRE (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 1\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;", 'GO', '', '-- ----- OPERATION_TYPE 2 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-03 11:00:00';", "-- OPERATION_TYPE 2: Max up. File 2 KANBAN first (the new Max), then file 3 EXPORT_POST (the destinations use it).\n-- Upload order of these parts: 2 KANBAN -> 3 EXPORT_POST\n-- Kanban rows -> file 2 KANBAN (LLM9Q910)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 2\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 3 EXPORT_POST (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 2\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;", 'GO', '', '-- ----- OPERATION_TYPE 3 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-28 10:00:00';", "-- OPERATION_TYPE 3: Max same (only Pcs/Case, or a new period with the same Max). File 2 KANBAN, then file 3 EXPORT_POST when the part has Export rows.\n-- Upload order of these parts: 2 KANBAN -> 3 EXPORT_POST\n-- Kanban rows -> file 2 KANBAN (LLM9Q910)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 3\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 3 EXPORT_POST (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 3\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;", 'GO', '', '-- ----- OPERATION_TYPE 4 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-05 11:00:00';", "-- OPERATION_TYPE 4: Never sent. File 2 KANBAN first so AP POLE knows the part, then file 3 EXPORT_POST.\n-- Upload order of these parts: 2 KANBAN -> 3 EXPORT_POST\n-- Kanban rows -> file 2 KANBAN (LLM9Q910)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 4\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 3 EXPORT_POST (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 4\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;", 'GO', '', '-- ----- OPERATION_TYPE 5 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-08 11:00:00';", "-- OPERATION_TYPE 5: Only the destinations changed. The Kanban row is a header (ACTION KEEP) and is not uploaded: the Kanban query returns no row. File 3 EXPORT_POST only.\n-- Upload order of these parts: 3 EXPORT_POST only\n-- Kanban rows -> file 2 KANBAN (LLM9Q910); returns no row for 5 (header not uploaded)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 5\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 3 EXPORT_POST (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 5\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;\n-- The header rows (5) of the run, for information\nSELECT h.PERIOD, h.PART_NO, h.ACTION, h.PART_STATUS, h.SHIPPING_BOX_QTY, h.MAX_SHIPPING_BOX_QTY, h.OPERATION_TYPE\nFROM   TB_H_STG_APPOLE_KANBAN h\nWHERE  h.SYNC_STATUS = '1' AND h.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 5\nORDER BY h.PERIOD, h.PART_NO;", 'GO', '', '-- ----- every row of a run with its OPERATION_TYPE -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-10 11:00:00';", "-- Every row the robot uploads in the run, with the OPERATION_TYPE of its part, in upload order\nSELECT e.FILE_NO, e.FILE_NAME, h.OPERATION_TYPE, e.NSP_PART_NO AS PART, e.PERIOD, e.ROW_ORDER,\n       e.EFFECTIVE_MONTH_YEAR, e.BUYER_PD, e.ORDER_TYPE, e.MAX_SHIPPING_BOX_RCS AS RCS, NULL AS SHIPPING_BOX_QTY, NULL AS MAX_SHIPPING_BOX_QTY\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT\nUNION ALL\nSELECT k.FILE_NO, 'KANBAN', k.OPERATION_TYPE, k.PART_NO, k.PERIOD, NULL,\n       k.EFFECTIVE_MONTH_YEAR, NULL, NULL, NULL, k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT\nORDER BY FILE_NO, PERIOD, PART, ROW_ORDER;", 'GO', ''] WHERE SYNC_STATUS = '1' AND SYNC_DT = @SYNC_DT;

-- XD06 GTOPAS
SELECT STG_ID, ACTION, DEPOT_CODE, P_NO, DESTINATION_CODE, MAKER_CODE, DOMESTIC_OVERSEAS, TOPAS_ORDER_TYPE, ORDER_TRANSPORTATION_CODE
FROM ['-- =====================================================================================================', '-- Crossdock staging: get queries of the robot XD07 per OPERATION_TYPE (SQL Server)', '-- Generated by deliverables/function_list_v2/erd/proposal_staging_sync/simulation/sql_studio/build_sql_studio.py', '-- Read-only DB user. @SYNC_DT = SYNC_DT of the run, given by the parent flow. The robot itself reads the three files with', '-- FILE_NO (see crossdock_staging_sync.sql, section 5); these queries split the same rows per OPERATION_TYPE to check a run.', '-- Columns in the order of the templates (LLM9Q910 / LLM9Q880), helper columns last. EFFECTIVE_MONTH_YEAR (MM/YYYY):', '-- the robot splits it into Effective Month and Effective Year. Example runs: data of crossdock_staging_simulation.sql.', '--   OPERATION_TYPE  example run           upload order', '--   1               2026-12-03 11:00:00   1 EXPORT_PRE -> 2 KANBAN', '--   2               2026-12-03 11:00:00   2 KANBAN -> 3 EXPORT_POST', '--   3               2026-12-28 10:00:00   2 KANBAN -> 3 EXPORT_POST', '--   4               2026-12-05 11:00:00   2 KANBAN -> 3 EXPORT_POST', '--   5               2026-12-08 11:00:00   3 EXPORT_POST only', '-- =====================================================================================================', '', '-- ----- OPERATION_TYPE 1 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-03 11:00:00';", "-- OPERATION_TYPE 1: Max down. File 1 EXPORT_PRE first (the destinations go down while AP POLE still has the old Max), then file 2 KANBAN with the new Max. No EXPORT_POST row for the part.\n-- Upload order of these parts: 1 EXPORT_PRE -> 2 KANBAN\n-- Kanban rows -> file 2 KANBAN (LLM9Q910)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 1\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 1 EXPORT_PRE (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 1\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;", 'GO', '', '-- ----- OPERATION_TYPE 2 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-03 11:00:00';", "-- OPERATION_TYPE 2: Max up. File 2 KANBAN first (the new Max), then file 3 EXPORT_POST (the destinations use it).\n-- Upload order of these parts: 2 KANBAN -> 3 EXPORT_POST\n-- Kanban rows -> file 2 KANBAN (LLM9Q910)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 2\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 3 EXPORT_POST (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 2\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;", 'GO', '', '-- ----- OPERATION_TYPE 3 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-28 10:00:00';", "-- OPERATION_TYPE 3: Max same (only Pcs/Case, or a new period with the same Max). File 2 KANBAN, then file 3 EXPORT_POST when the part has Export rows.\n-- Upload order of these parts: 2 KANBAN -> 3 EXPORT_POST\n-- Kanban rows -> file 2 KANBAN (LLM9Q910)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 3\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 3 EXPORT_POST (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 3\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;", 'GO', '', '-- ----- OPERATION_TYPE 4 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-05 11:00:00';", "-- OPERATION_TYPE 4: Never sent. File 2 KANBAN first so AP POLE knows the part, then file 3 EXPORT_POST.\n-- Upload order of these parts: 2 KANBAN -> 3 EXPORT_POST\n-- Kanban rows -> file 2 KANBAN (LLM9Q910)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 4\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 3 EXPORT_POST (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 4\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;", 'GO', '', '-- ----- OPERATION_TYPE 5 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-08 11:00:00';", "-- OPERATION_TYPE 5: Only the destinations changed. The Kanban row is a header (ACTION KEEP) and is not uploaded: the Kanban query returns no row. File 3 EXPORT_POST only.\n-- Upload order of these parts: 3 EXPORT_POST only\n-- Kanban rows -> file 2 KANBAN (LLM9Q910); returns no row for 5 (header not uploaded)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 5\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 3 EXPORT_POST (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 5\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;\n-- The header rows (5) of the run, for information\nSELECT h.PERIOD, h.PART_NO, h.ACTION, h.PART_STATUS, h.SHIPPING_BOX_QTY, h.MAX_SHIPPING_BOX_QTY, h.OPERATION_TYPE\nFROM   TB_H_STG_APPOLE_KANBAN h\nWHERE  h.SYNC_STATUS = '1' AND h.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 5\nORDER BY h.PERIOD, h.PART_NO;", 'GO', '', '-- ----- every row of a run with its OPERATION_TYPE -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-10 11:00:00';", "-- Every row the robot uploads in the run, with the OPERATION_TYPE of its part, in upload order\nSELECT e.FILE_NO, e.FILE_NAME, h.OPERATION_TYPE, e.NSP_PART_NO AS PART, e.PERIOD, e.ROW_ORDER,\n       e.EFFECTIVE_MONTH_YEAR, e.BUYER_PD, e.ORDER_TYPE, e.MAX_SHIPPING_BOX_RCS AS RCS, NULL AS SHIPPING_BOX_QTY, NULL AS MAX_SHIPPING_BOX_QTY\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT\nUNION ALL\nSELECT k.FILE_NO, 'KANBAN', k.OPERATION_TYPE, k.PART_NO, k.PERIOD, NULL,\n       k.EFFECTIVE_MONTH_YEAR, NULL, NULL, NULL, k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT\nORDER BY FILE_NO, PERIOD, PART, ROW_ORDER;", 'GO', ''] WHERE SYNC_STATUS = '1' AND SYNC_DT = @SYNC_DT ORDER BY P_NO, DESTINATION_CODE;

-- XD07 file 1 EXPORT_PRE, file 2 KANBAN, file 3 EXPORT_POST (a file without rows is not made)
SELECT * FROM V_APPOLE_UPLOAD_EXPORT WHERE SYNC_DT = @SYNC_DT AND FILE_NO = 1 ORDER BY PERIOD, NSP_PART_NO, ROW_ORDER, STG_ID;
SELECT * FROM V_APPOLE_UPLOAD_KANBAN WHERE SYNC_DT = @SYNC_DT ORDER BY PERIOD, PART_NO;
SELECT * FROM V_APPOLE_UPLOAD_EXPORT WHERE SYNC_DT = @SYNC_DT AND FILE_NO = 3 ORDER BY PERIOD, NSP_PART_NO, ROW_ORDER, STG_ID;

-- Headers of the run: OPERATION_TYPE decides the file of the Export rows of the part
SELECT k.PERIOD, k.PART_NO, k.ACTION, k.OPERATION_TYPE,
       CASE k.OPERATION_TYPE WHEN 1 THEN 'EXPORT_PRE -> KANBAN' WHEN 5 THEN 'EXPORT_POST only (header not uploaded)'
                             ELSE 'KANBAN -> EXPORT_POST' END AS UPLOAD_ORDER
FROM TB_H_STG_APPOLE_KANBAN k WHERE k.SYNC_STATUS = '1' AND k.SYNC_DT = @SYNC_DT ORDER BY k.PERIOD, k.PART_NO;

-- Every run: Kanban headers and their OPERATION_TYPE (SQL Server 2017 or later for STRING_AGG)
SELECT k.SYNC_DT, STRING_AGG(CONCAT(k.PART_NO, ' ', k.PERIOD, ' = ', k.OPERATION_TYPE), ', ') AS HEADERS
FROM TB_H_STG_APPOLE_KANBAN k WHERE k.SYNC_STATUS = '1' GROUP BY k.SYNC_DT ORDER BY k.SYNC_DT;

-- Every Kanban row per OPERATION_TYPE with the Max sent before it
SELECT k.OPERATION_TYPE, k.SYNC_DT, k.PERIOD, k.PART_NO, k.ACTION,
       LAG(k.MAX_SHIPPING_BOX_QTY) OVER (PARTITION BY k.PART_NO ORDER BY k.PERIOD, k.SYNC_DT, k.STG_ID) AS PREV_MAX,
       k.MAX_SHIPPING_BOX_QTY AS MAX_NOW, k.SHIPPING_BOX_QTY
FROM TB_H_STG_APPOLE_KANBAN k WHERE k.SYNC_STATUS = '1' ORDER BY k.OPERATION_TYPE, k.SYNC_DT, k.PART_NO;

-- Rows waiting for the next [Sync]
SELECT 'KANBAN' AS TBL, STG_ID, PERIOD, PART_NO AS PART, ACTION FROM TB_H_STG_APPOLE_KANBAN WHERE SYNC_STATUS = '0'
UNION ALL SELECT 'EXPORT', STG_ID, PERIOD, NSP_PART_NO, ACTION FROM TB_H_STG_APPOLE_EXPORT WHERE SYNC_STATUS = '0'
UNION ALL SELECT 'GTOPAS', STG_ID, PERIOD, P_NO, ACTION FROM ['-- =====================================================================================================', '-- Crossdock staging: get queries of the robot XD07 per OPERATION_TYPE (SQL Server)', '-- Generated by deliverables/function_list_v2/erd/proposal_staging_sync/simulation/sql_studio/build_sql_studio.py', '-- Read-only DB user. @SYNC_DT = SYNC_DT of the run, given by the parent flow. The robot itself reads the three files with', '-- FILE_NO (see crossdock_staging_sync.sql, section 5); these queries split the same rows per OPERATION_TYPE to check a run.', '-- Columns in the order of the templates (LLM9Q910 / LLM9Q880), helper columns last. EFFECTIVE_MONTH_YEAR (MM/YYYY):', '-- the robot splits it into Effective Month and Effective Year. Example runs: data of crossdock_staging_simulation.sql.', '--   OPERATION_TYPE  example run           upload order', '--   1               2026-12-03 11:00:00   1 EXPORT_PRE -> 2 KANBAN', '--   2               2026-12-03 11:00:00   2 KANBAN -> 3 EXPORT_POST', '--   3               2026-12-28 10:00:00   2 KANBAN -> 3 EXPORT_POST', '--   4               2026-12-05 11:00:00   2 KANBAN -> 3 EXPORT_POST', '--   5               2026-12-08 11:00:00   3 EXPORT_POST only', '-- =====================================================================================================', '', '-- ----- OPERATION_TYPE 1 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-03 11:00:00';", "-- OPERATION_TYPE 1: Max down. File 1 EXPORT_PRE first (the destinations go down while AP POLE still has the old Max), then file 2 KANBAN with the new Max. No EXPORT_POST row for the part.\n-- Upload order of these parts: 1 EXPORT_PRE -> 2 KANBAN\n-- Kanban rows -> file 2 KANBAN (LLM9Q910)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 1\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 1 EXPORT_PRE (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 1\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;", 'GO', '', '-- ----- OPERATION_TYPE 2 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-03 11:00:00';", "-- OPERATION_TYPE 2: Max up. File 2 KANBAN first (the new Max), then file 3 EXPORT_POST (the destinations use it).\n-- Upload order of these parts: 2 KANBAN -> 3 EXPORT_POST\n-- Kanban rows -> file 2 KANBAN (LLM9Q910)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 2\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 3 EXPORT_POST (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 2\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;", 'GO', '', '-- ----- OPERATION_TYPE 3 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-28 10:00:00';", "-- OPERATION_TYPE 3: Max same (only Pcs/Case, or a new period with the same Max). File 2 KANBAN, then file 3 EXPORT_POST when the part has Export rows.\n-- Upload order of these parts: 2 KANBAN -> 3 EXPORT_POST\n-- Kanban rows -> file 2 KANBAN (LLM9Q910)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 3\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 3 EXPORT_POST (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 3\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;", 'GO', '', '-- ----- OPERATION_TYPE 4 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-05 11:00:00';", "-- OPERATION_TYPE 4: Never sent. File 2 KANBAN first so AP POLE knows the part, then file 3 EXPORT_POST.\n-- Upload order of these parts: 2 KANBAN -> 3 EXPORT_POST\n-- Kanban rows -> file 2 KANBAN (LLM9Q910)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 4\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 3 EXPORT_POST (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 4\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;", 'GO', '', '-- ----- OPERATION_TYPE 5 -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-08 11:00:00';", "-- OPERATION_TYPE 5: Only the destinations changed. The Kanban row is a header (ACTION KEEP) and is not uploaded: the Kanban query returns no row. File 3 EXPORT_POST only.\n-- Upload order of these parts: 3 EXPORT_POST only\n-- Kanban rows -> file 2 KANBAN (LLM9Q910); returns no row for 5 (header not uploaded)\nSELECT k.FILE_NO, k.EFFECTIVE_MONTH_YEAR, k.OPERATOR_ID, k.PART_NO, k.PART_NAME,\n       k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY,\n       k.OPERATION_TYPE, k.PERIOD, k.STG_ID                          -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT AND k.OPERATION_TYPE = 5\nORDER BY k.PERIOD, k.PART_NO;\n-- Export rows -> file 3 EXPORT_POST (LLM9Q880); OPERATION_TYPE from the header of the part\nSELECT e.FILE_NO, e.FILE_NAME, e.EFFECTIVE_MONTH_YEAR, e.PART_NO, e.BUYER_PD, e.ORDER_TYPE,\n       e.TRANSPORT_CODE, e.MAX_SHIPPING_BOX_RCS,\n       h.OPERATION_TYPE, e.ROW_ORDER, e.PERIOD, e.NSP_PART_NO, e.STG_ID   -- helper columns, not written\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON  h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD\n       AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 5\nORDER BY e.FILE_NO, e.PERIOD, e.NSP_PART_NO, e.ROW_ORDER, e.STG_ID;\n-- The header rows (5) of the run, for information\nSELECT h.PERIOD, h.PART_NO, h.ACTION, h.PART_STATUS, h.SHIPPING_BOX_QTY, h.MAX_SHIPPING_BOX_QTY, h.OPERATION_TYPE\nFROM   TB_H_STG_APPOLE_KANBAN h\nWHERE  h.SYNC_STATUS = '1' AND h.SYNC_DT = @SYNC_DT AND h.OPERATION_TYPE = 5\nORDER BY h.PERIOD, h.PART_NO;", 'GO', '', '-- ----- every row of a run with its OPERATION_TYPE -----', "DECLARE @SYNC_DT DATETIME2(0) = '2026-12-10 11:00:00';", "-- Every row the robot uploads in the run, with the OPERATION_TYPE of its part, in upload order\nSELECT e.FILE_NO, e.FILE_NAME, h.OPERATION_TYPE, e.NSP_PART_NO AS PART, e.PERIOD, e.ROW_ORDER,\n       e.EFFECTIVE_MONTH_YEAR, e.BUYER_PD, e.ORDER_TYPE, e.MAX_SHIPPING_BOX_RCS AS RCS, NULL AS SHIPPING_BOX_QTY, NULL AS MAX_SHIPPING_BOX_QTY\nFROM   V_APPOLE_UPLOAD_EXPORT e\nJOIN   TB_H_STG_APPOLE_KANBAN h\n       ON h.SYNC_DT = e.SYNC_DT AND h.PERIOD = e.PERIOD AND h.PART_NO = e.NSP_PART_NO AND h.SYNC_STATUS = '1'\nWHERE  e.SYNC_DT = @SYNC_DT\nUNION ALL\nSELECT k.FILE_NO, 'KANBAN', k.OPERATION_TYPE, k.PART_NO, k.PERIOD, NULL,\n       k.EFFECTIVE_MONTH_YEAR, NULL, NULL, NULL, k.SHIPPING_BOX_QTY, k.MAX_SHIPPING_BOX_QTY\nFROM   V_APPOLE_UPLOAD_KANBAN k\nWHERE  k.SYNC_DT = @SYNC_DT\nORDER BY FILE_NO, PERIOD, PART, ROW_ORDER;", 'GO', ''] WHERE SYNC_STATUS = '0';

-- Check: one unsent row per key (expect no row)
SELECT PERIOD, NSP_PART_NO, DEST_CODE, ORDER_TYPE, COUNT(*) AS UNSENT FROM TB_H_STG_APPOLE_EXPORT WHERE SYNC_STATUS = '0'
